import math

# Total number of ways to arrange the numbers on the faces of a regular octahedron
total_ways = math.factorial(8)

# For each face, there are 5 other faces that do not share an edge with it
# So for each face, there are 5! ways to arrange the remaining numbers
valid_arrangements = 7 * math.factorial(5)

# Calculate the probability
probability = valid_arrangements / total_ways

# Fraction in its simplest form m/n
from fractions import Fraction
fraction = Fraction(probability).limit_denominator()

# Extract m and n
m, n = fraction.numerator, fraction.denominator

# Calculate m + n
result = m + n
print(result)
